<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import { corregirCritica, listarCriticas, obtenerCritica, urlReporteCritica, validarCritica } from '../services/criticaLecturas'
import type { Critica, Distrito, Option } from '../interfaces/criticaLecturas.interface'
const rows=ref<Critica[]>([]),distritos=ref<Distrito[]>([]),observaciones=ref<Option[]>([]),detail=ref<Critica|null>(null),modal=ref(false),edit=ref(false),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),total=ref(0),lastPage=ref(1),summary=reactive({pendientes:0,validados:0,total:0}),filters=reactive({criterio:'',distrito_id:'',estado:'pendiente',page:1}),form=reactive({lectura:'',observacion_id:''});const correctedConsumption=computed(()=>detail.value?form.observacion_id?detail.value.promedio:Math.max(0,Number(form.lectura)-detail.value.lectura_anterior):0);const pct=(x:Distrito)=>x.total?Math.round(x.validados*100/x.total):0
async function load(page=1){loading.value=true;error.value='';filters.page=page;try{const r=await listarCriticas(filters);rows.value=r.data;distritos.value=r.distritos;observaciones.value=r.observaciones;total.value=r.total;lastPage.value=r.last_page;Object.assign(summary,r.resumen)}catch(e){error.value=msg(e)}finally{loading.value=false}}async function open(id:number){error.value='';try{detail.value=await obtenerCritica(id);form.lectura=String(detail.value.lectura_actual);form.observacion_id='';edit.value=false;modal.value=true}catch(e){error.value=msg(e)}}async function approve(){if(!detail.value||!confirm('¿Validar esta lectura sin modificaciones?'))return;saving.value=true;try{await validarCritica(detail.value.id);success.value='Lectura validada correctamente.';modal.value=false;await load(filters.page)}catch(e){error.value=msg(e)}finally{saving.value=false}}async function correct(){if(!detail.value)return;if(!form.observacion_id&&(!form.lectura||Number(form.lectura)<detail.value.lectura_anterior)){error.value='Ingrese una lectura igual o mayor que la anterior.';return}saving.value=true;error.value='';try{await corregirCritica(detail.value.id,{lectura:Number(form.lectura),observacion_id:form.observacion_id?Number(form.observacion_id):undefined});success.value='Lectura corregida y validada correctamente.';modal.value=false;await load(filters.page)}catch(e){error.value=msg(e)}finally{saving.value=false}}function choose(id:number){filters.distrito_id=String(id);load(1)}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Medición / Crítica de lecturas</nav><header class="hero"><div class="mark">CR</div><div><small>EVAN · CONTROL DE MEDICIÓN</small><h1>Crítica de lecturas</h1><p>Revisión, corrección y validación de consumos observados.</p></div><div class="stats"><div><b>{{summary.pendientes}}</b><span>Pendientes</span></div><div><b>{{summary.validados}}</b><span>Validadas</span></div><div><b>{{summary.total}}</b><span>Total</span></div></div></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="districts"><button v-for="x in distritos" :key="x.id" :class="{active:filters.distrito_id==String(x.id)}" @click="choose(x.id)"><span>{{x.nombre}}</span><b>{{x.validados}} / {{x.total}}</b><i><em :style="{width:pct(x)+'%'}"></em></i></button></section><section class="filters"><label>Buscar medidor<input v-model.trim="filters.criterio" placeholder="Número de medidor" @keyup.enter="load(1)"></label><label>Estado<select v-model="filters.estado"><option value="pendiente">Pendientes de validación</option><option value="validado">Validadas</option><option value="">Todas</option></select></label><button @click="load(1)">Consultar</button><a v-if="filters.distrito_id" :href="urlReporteCritica(filters.distrito_id)" target="_blank">Imprimir crítica</a></section><div v-if="loading" class="empty">Cargando críticas…</div><div v-else-if="!rows.length" class="empty">No existen lecturas críticas en la selección.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id" :class="{done:x.validado}"><header><span>{{x.distrito}}</span><em>{{x.validado?'Validada':'Pendiente'}}</em></header><h2>{{x.cliente}}</h2><p>{{x.direccion}}</p><div class="issue"><span>{{x.tipo_error}}</span><b>{{x.lectura_atipica}}</b></div><dl><div><dt>Medidor</dt><dd>{{x.medidor}}</dd></div><div><dt>Suministro</dt><dd>{{x.suministro}}</dd></div><div><dt>Lectura anterior</dt><dd>{{x.lectura_anterior}}</dd></div><div><dt>Lectura actual</dt><dd>{{x.lectura_actual}}</dd></div><div><dt>Consumo</dt><dd>{{x.consumo}} m³</dd></div><div><dt>Promedio</dt><dd>{{x.promedio}} m³</dd></div></dl><button @click="open(x.id)">{{x.validado?'Ver detalle':'Revisar crítica'}}</button></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}} · {{total}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal&&detail" class="backdrop" @mousedown.self="modal=false"><section class="modal"><header><div><small>MEDIDOR {{detail.medidor}}</small><h2>{{detail.cliente}}</h2><p>{{detail.direccion}}</p></div><button @click="modal=false">×</button></header><div class="issue large"><span>{{detail.tipo_error}}</span><b>{{detail.lectura_atipica}}</b></div><section class="values"><div><span>Consumo anterior</span><b>{{detail.consumo_anterior}} m³</b></div><div><span>Promedio</span><b>{{detail.promedio}} m³</b></div><div><span>Lectura anterior</span><b>{{detail.lectura_anterior}}</b></div><div><span>Lectura actual</span><b>{{detail.lectura_actual}}</b></div><div><span>Consumo actual</span><b>{{detail.consumo}} m³</b></div><div><span>Lecturista</span><b>{{detail.lecturista}}</b></div></section><div class="photos"><a v-for="(x,i) in detail.fotografias" :key="i" :href="x" target="_blank"><img :src="x" :alt="`Evidencia ${i+1}`"></a></div><template v-if="!detail.validado&&!edit"><footer><button class="clear" @click="modal=false">Cancelar</button><button class="change" @click="edit=true">Corregir lectura</button><button :disabled="saving" @click="approve">Validar sin cambios</button></footer></template><template v-else-if="!detail.validado"><section class="editor"><h3>Corrección de lectura</h3><label>Nueva lectura<input v-model="form.lectura" type="number" :min="detail.lectura_anterior"></label><div class="warning">Si elige una observación, no se considerará la nueva lectura y se utilizará el consumo promedio.</div><label>Observación<select v-model="form.observacion_id"><option value="">Sin observación</option><option v-for="x in observaciones" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><div class="result"><span>Consumo resultante</span><b>{{correctedConsumption}} m³</b></div></section><footer><button class="clear" @click="edit=false">Volver</button><button :disabled="saving" @click="correct">{{saving?'Guardando…':'Guardar corrección'}}</button></footer></template><footer v-else><button class="clear" @click="modal=false">Cerrar</button></footer></section></div></div></template>
<style scoped>
.page{--a:#b3484c;color:#37464d}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small,.modal small{color:var(--a);font-size:.53rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p,.modal header p{margin:0;color:#7c898f;font-size:.62rem}.stats{margin-left:auto;display:flex}.stats div{min-width:70px;text-align:center}.stats b,.stats span{display:block}.stats b{font-size:.85rem}.stats span{font-size:.42rem}.flash{padding:10px;font-size:.6rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.districts{margin-top:12px;display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.districts button{padding:10px;border:1px solid transparent;border-radius:7px;background:#fff;text-align:left}.districts button.active{border-color:var(--a)}.districts span,.districts b{display:block;font-size:.48rem}.districts b{color:var(--a)}.districts i{height:4px;display:block;background:#ecdfe0}.districts em{height:100%;display:block;background:var(--a)}.filters{margin-top:8px;padding:12px;display:flex;align-items:end;gap:8px;background:#fff}.filters label{flex:1;font-size:.47rem}input,select{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.52rem}.filters button,.filters a,.pages button,.cards>article>button,.modal footer button{padding:8px 11px;border:0;border-radius:5px;color:#fff;background:var(--a);text-decoration:none;font-size:.49rem}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.cards article{padding:14px;border-top:3px solid var(--a);border-radius:8px;background:#fff}.cards article.done{border-color:#278064}.cards header{display:flex;justify-content:space-between;font-size:.44rem}.cards em{color:var(--a);font-style:normal}.cards h2{margin:10px 0 2px;font-size:.64rem}.cards>article>p{min-height:30px;color:#748187;font-size:.48rem}.issue{padding:8px;display:flex;justify-content:space-between;color:#963e43;background:#fff0f0;font-size:.5rem}.cards dl{display:grid;grid-template-columns:1fr 1fr;gap:6px}.cards dt{color:#89959a;font-size:.4rem}.cards dd{margin:2px 0;font-size:.48rem;font-weight:700}.cards>article>button{width:100%}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.pages{display:flex;justify-content:center;align-items:center;gap:8px;font-size:.48rem}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(100%,760px);max-height:94vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:.9rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.large{margin-top:12px}.values{margin:10px 0;display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.values div,.result{padding:9px;background:#f6f2f2}.values span,.values b,.result span,.result b{display:block;font-size:.48rem}.photos{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.photos img{width:100%;height:110px;object-fit:cover}.modal footer{margin-top:12px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#64737a!important;background:#edf1f2!important}.change{background:#b77b2f!important}.editor{margin-top:12px;padding:12px;background:#f8f9f9}.editor h3{font-size:.58rem}.editor label{display:block;margin:8px 0;font-size:.48rem}.warning{padding:8px;color:#8f601f;background:#fff2da;font-size:.48rem}@media(max-width:850px){.districts{grid-template-columns:1fr 1fr}.cards{grid-template-columns:1fr 1fr}}@media(max-width:540px){.hero{flex-wrap:wrap}.stats{margin-left:0;width:100%}.filters{align-items:stretch;flex-direction:column}.cards,.districts,.values{grid-template-columns:1fr}}
